begin;
create temporary table arenax_test_results (test text, passed boolean);
grant select,insert on arenax_test_results to authenticated;
do $$
declare v_org uuid; v_event uuid; v_other uuid; v_sport uuid; v_team uuid; v_reg uuid; v_member uuid;
begin
 select sport_id into strict v_sport from public.events where event_name='ArenaX India States Cricket Cup 2027';
 insert into public.organizations(name,slug,country,timezone)
 values('ArenaX check-in transaction test','check-in-test-'||gen_random_uuid(),'India','Asia/Kolkata') returning id into v_org;
 insert into public.events(organization_id,sport_id,event_name,start_date,end_date,registration_type,status)
 values(v_org,v_sport,'ArenaX International Check-In Test',current_date,current_date,'BOTH','IN_PROGRESS') returning id into v_event;
 insert into public.events(organization_id,sport_id,event_name,start_date,end_date,registration_type,status)
 values(v_org,v_sport,'ArenaX India States Isolation Test',current_date,current_date,'BOTH','IN_PROGRESS') returning id into v_other;
 insert into public.teams(event_id,team_name,registration_status,approval_status)
 values(v_event,'Bihar','APPROVED','APPROVED') returning id into v_team;
 insert into public.team_members(team_id,user_id,team_role,status,invitation_status,waiver_status)
 values(v_team,'a289ed2b-99c9-4aad-affc-d3ca89ebcfbb','PLAYER','ACTIVE','ACCEPTED','ACCEPTED') returning id into v_member;
 insert into public.registrations(event_id,team_id,registration_type,registration_status,waiver_status,payment_status)
 values(v_event,v_team,'TEAM','APPROVED','NOT_REQUIRED','NOT_REQUIRED') returning id into v_reg;
 insert into public.registrations(event_id,user_id,registration_type,registration_status,waiver_status,payment_status)
 values(v_event,'3514e1cc-fca6-478b-a760-cb83eefac27e','INDIVIDUAL','APPROVED','NOT_REQUIRED','NOT_REQUIRED');
 perform set_config('arenax.test_event',v_event::text,true);
 perform set_config('arenax.other_event',v_other::text,true);
 perform set_config('arenax.test_org',v_org::text,true);
 perform set_config('arenax.test_reg',v_reg::text,true);
 perform set_config('arenax.test_member',v_member::text,true);
end; $$;
reset role; select set_config('request.jwt.claim.sub','a289ed2b-99c9-4aad-affc-d3ca89ebcfbb',true); select set_config('request.jwt.claims','{"sub":"a289ed2b-99c9-4aad-affc-d3ca89ebcfbb","role":"authenticated"}',true); set local role authenticated;
do $$ begin begin perform public.check_in_event_participant(current_setting('arenax.test_event')::uuid,'3514e1cc-fca6-478b-a760-cb83eefac27e'); raise exception 'Unexpected success: ordinary player cannot check in another participant'; exception when sqlstate '42501' then null; end; insert into arenax_test_results values('ordinary player cannot check in another participant',true); end; $$;
do $$ begin begin perform public.check_in_event_participant(current_setting('arenax.test_event')::uuid,'a289ed2b-99c9-4aad-affc-d3ca89ebcfbb'); raise exception 'Unexpected success: ordinary player cannot self check in'; exception when sqlstate '42501' then null; end; insert into arenax_test_results values('ordinary player cannot self check in',true); end; $$;
do $$ begin begin perform * from public.issue_event_check_in_qr(current_setting('arenax.test_event')::uuid,'3514e1cc-fca6-478b-a760-cb83eefac27e'); raise exception 'Unexpected success: ordinary player cannot issue someone elses QR'; exception when sqlstate '42501' then null; end; insert into arenax_test_results values('ordinary player cannot issue someone elses QR',true); end; $$;
do $$ begin begin insert into public.event_check_ins(event_id,participant_user_id,registration_id,check_in_method,checked_in_by) values(current_setting('arenax.test_event')::uuid,'a289ed2b-99c9-4aad-affc-d3ca89ebcfbb',current_setting('arenax.test_reg')::uuid,'MANUAL','3514e1cc-fca6-478b-a760-cb83eefac27e'); raise exception 'Unexpected success: attendance insert cannot forge operator'; exception when sqlstate '42501' then null; end; insert into arenax_test_results values('attendance insert cannot forge operator',true); end; $$;
do $$ begin begin update public.event_check_ins set checked_in_by='a289ed2b-99c9-4aad-affc-d3ca89ebcfbb'; raise exception 'Unexpected success: attendance update forbidden'; exception when sqlstate '42501' then null; end; insert into arenax_test_results values('attendance update forbidden',true); end; $$;
do $$ begin begin delete from public.event_check_ins; raise exception 'Unexpected success: attendance delete forbidden'; exception when sqlstate '42501' then null; end; insert into arenax_test_results values('attendance delete forbidden',true); end; $$;
do $$ begin begin perform * from arenax_private.check_in_tokens; raise exception 'Unexpected success: QR token hashes inaccessible'; exception when sqlstate '42501' then null; end; insert into arenax_test_results values('QR token hashes inaccessible',true); end; $$;
do $$ begin begin perform * from arenax_private.check_in_eligibility(current_setting('arenax.test_event')::uuid,'3514e1cc-fca6-478b-a760-cb83eefac27e'); raise exception 'Unexpected success: internal eligibility resolver inaccessible'; exception when sqlstate '42501' then null; end; insert into arenax_test_results values('internal eligibility resolver inaccessible',true); end; $$;
do $$ begin perform set_config('arenax.player_qr',(select qr_token from public.issue_event_check_in_qr(current_setting('arenax.test_event')::uuid,'a289ed2b-99c9-4aad-affc-d3ca89ebcfbb')),true); insert into arenax_test_results values('eligible participant can issue own QR',true); end; $$;
reset role; insert into public.event_staff_assignments(event_id,user_id,staff_role,status) values(current_setting('arenax.test_event')::uuid,'a289ed2b-99c9-4aad-affc-d3ca89ebcfbb','SCORER','CONFIRMED'); set local role authenticated;
do $$ begin begin perform public.check_in_event_participant(current_setting('arenax.test_event')::uuid,'3514e1cc-fca6-478b-a760-cb83eefac27e'); raise exception 'Unexpected success: SCORER alone cannot check in'; exception when sqlstate '42501' then null; end; insert into arenax_test_results values('SCORER alone cannot check in',true); end; $$;
reset role; select set_config('request.jwt.claim.sub','3514e1cc-fca6-478b-a760-cb83eefac27e',true); select set_config('request.jwt.claims','{"sub":"3514e1cc-fca6-478b-a760-cb83eefac27e","role":"authenticated"}',true); set local role authenticated;
do $$ begin declare v public.event_check_ins; begin v:=public.check_in_event_participant(current_setting('arenax.test_event')::uuid,'a289ed2b-99c9-4aad-affc-d3ca89ebcfbb'); if v.checked_in_by<>'3514e1cc-fca6-478b-a760-cb83eefac27e'::uuid or v.team_member_id is null or v.check_in_method<>'MANUAL' or v.checked_in_at is null then raise exception 'Audit mismatch'; end if; perform set_config('arenax.first_checkin',to_jsonb(v)::text,true); end; insert into arenax_test_results values('Super Admin manual team participant check-in',true); end; $$;
do $$ begin if to_jsonb(public.check_in_event_participant(current_setting('arenax.test_event')::uuid,'a289ed2b-99c9-4aad-affc-d3ca89ebcfbb')) is distinct from current_setting('arenax.first_checkin')::jsonb then raise exception 'Duplicate changed original'; end if; insert into arenax_test_results values('duplicate manual check-in preserves audit',true); end; $$;
reset role; select set_config('request.jwt.claim.sub','a289ed2b-99c9-4aad-affc-d3ca89ebcfbb',true); select set_config('request.jwt.claims','{"sub":"a289ed2b-99c9-4aad-affc-d3ca89ebcfbb","role":"authenticated"}',true); set local role authenticated;
do $$ begin if (select count(*) from public.event_check_ins where event_id=current_setting('arenax.test_event')::uuid)<>1 then raise exception 'Own attendance missing'; end if; insert into arenax_test_results values('participant can read own attendance',true); end; $$;
reset role; insert into public.event_staff_assignments(event_id,user_id,staff_role,status) values(current_setting('arenax.test_event')::uuid,'a289ed2b-99c9-4aad-affc-d3ca89ebcfbb','CHECK_IN','CONFIRMED'); set local role authenticated;
do $$ begin if public.can_check_in_event(current_setting('arenax.test_event')::uuid) is distinct from true or public.can_manage_event(current_setting('arenax.test_event')::uuid) is distinct from false then raise exception 'Wrong check-in permission'; end if; insert into arenax_test_results values('CHECK_IN assignment grants only check-in rights',true); end; $$;
do $$ begin begin perform public.check_in_event_participant(current_setting('arenax.other_event')::uuid,'3514e1cc-fca6-478b-a760-cb83eefac27e'); raise exception 'Unexpected success: CHECK_IN cannot act in another event'; exception when sqlstate '42501' then null; end; insert into arenax_test_results values('CHECK_IN cannot act in another event',true); end; $$;
do $$ begin perform set_config('arenax.old_qr',(select qr_token from public.issue_event_check_in_qr(current_setting('arenax.test_event')::uuid,'3514e1cc-fca6-478b-a760-cb83eefac27e')),true); insert into arenax_test_results values('CHECK_IN staff can issue participant QR',true); end; $$;
do $$ begin perform set_config('arenax.qr',(select qr_token from public.issue_event_check_in_qr(current_setting('arenax.test_event')::uuid,'3514e1cc-fca6-478b-a760-cb83eefac27e')),true); if current_setting('arenax.qr')=current_setting('arenax.old_qr') then raise exception 'Token not rotated'; end if; insert into arenax_test_results values('QR rotation replaces token',true); end; $$;
do $$ begin begin perform public.check_in_event_participant(current_setting('arenax.test_event')::uuid,'3514e1cc-fca6-478b-a760-cb83eefac27e','QR',current_setting('arenax.old_qr')); raise exception 'Unexpected success: rotated QR rejected'; exception when sqlstate '22023' then null; end; insert into arenax_test_results values('rotated QR rejected',true); end; $$;
do $$ begin begin perform public.check_in_event_participant(current_setting('arenax.test_event')::uuid,'a289ed2b-99c9-4aad-affc-d3ca89ebcfbb','QR',current_setting('arenax.qr')); raise exception 'Unexpected success: QR cannot be used for another participant'; exception when sqlstate '22023' then null; end; insert into arenax_test_results values('QR cannot be used for another participant',true); end; $$;
do $$ begin begin perform public.check_in_event_participant(current_setting('arenax.test_event')::uuid,'3514e1cc-fca6-478b-a760-cb83eefac27e','QR',repeat('a',64)); raise exception 'Unexpected success: invalid QR rejected'; exception when sqlstate '22023' then null; end; insert into arenax_test_results values('invalid QR rejected',true); end; $$;
do $$ begin begin perform public.check_in_event_participant(current_setting('arenax.test_event')::uuid,'3514e1cc-fca6-478b-a760-cb83eefac27e',null); raise exception 'Unexpected success: null check-in method rejected'; exception when sqlstate '22023' then null; end; insert into arenax_test_results values('null check-in method rejected',true); end; $$;
reset role; update arenax_private.check_in_tokens set issued_at=clock_timestamp()-interval '2 days',expires_at=clock_timestamp()-interval '1 day' where event_id=current_setting('arenax.test_event')::uuid and participant_user_id='3514e1cc-fca6-478b-a760-cb83eefac27e'; set local role authenticated;
do $$ begin begin perform public.check_in_event_participant(current_setting('arenax.test_event')::uuid,'3514e1cc-fca6-478b-a760-cb83eefac27e','QR',current_setting('arenax.qr')); raise exception 'Unexpected success: expired QR rejected'; exception when sqlstate '22023' then null; end; insert into arenax_test_results values('expired QR rejected',true); end; $$;
do $$ begin perform set_config('arenax.qr',(select qr_token from public.issue_event_check_in_qr(current_setting('arenax.test_event')::uuid,'3514e1cc-fca6-478b-a760-cb83eefac27e')),true); insert into arenax_test_results values('expired QR can be replaced',true); end; $$;
do $$ begin declare v public.event_check_ins; begin v:=public.check_in_event_participant(current_setting('arenax.test_event')::uuid,'3514e1cc-fca6-478b-a760-cb83eefac27e','QR',current_setting('arenax.qr')); if v.checked_in_by<>'a289ed2b-99c9-4aad-affc-d3ca89ebcfbb'::uuid or v.team_member_id is not null or v.check_in_method<>'QR' then raise exception 'QR audit mismatch'; end if; perform set_config('arenax.qr_result',to_jsonb(v)::text,true); end; insert into arenax_test_results values('CHECK_IN staff QR individual check-in',true); end; $$;
do $$ begin if to_jsonb(public.check_in_event_participant(current_setting('arenax.test_event')::uuid,'3514e1cc-fca6-478b-a760-cb83eefac27e','QR',current_setting('arenax.qr'))) is distinct from current_setting('arenax.qr_result')::jsonb then raise exception 'QR retry changed audit'; end if; insert into arenax_test_results values('QR retry is idempotent',true); end; $$;
do $$ begin if (select count(*) from public.event_check_ins where event_id=current_setting('arenax.test_event')::uuid)<>2 then raise exception 'Wrong attendance visibility'; end if; insert into arenax_test_results values('CHECK_IN staff sees event attendance',true); end; $$;
reset role; update public.event_staff_assignments set status='CANCELLED' where event_id=current_setting('arenax.test_event')::uuid and staff_role='CHECK_IN'; set local role authenticated;
do $$ begin begin perform public.check_in_event_participant(current_setting('arenax.test_event')::uuid,'3514e1cc-fca6-478b-a760-cb83eefac27e'); raise exception 'Unexpected success: cancelled CHECK_IN assignment immediately denied'; exception when sqlstate '42501' then null; end; insert into arenax_test_results values('cancelled CHECK_IN assignment immediately denied',true); end; $$;
do $$ begin if (select count(*) from public.event_check_ins where event_id=current_setting('arenax.test_event')::uuid)<>1 then raise exception 'Attendance leaked'; end if; insert into arenax_test_results values('SCORER cannot read other participants attendance',true); end; $$;
reset role; insert into public.user_roles(user_id,organization_id,role,status) values('a289ed2b-99c9-4aad-affc-d3ca89ebcfbb',current_setting('arenax.test_org')::uuid,'ORGANIZER','ACTIVE'); set local role authenticated;
do $$ begin if public.can_check_in_event(current_setting('arenax.test_event')::uuid) is distinct from true then raise exception 'Organizer denied'; end if; perform public.check_in_event_participant(current_setting('arenax.test_event')::uuid,'3514e1cc-fca6-478b-a760-cb83eefac27e'); insert into arenax_test_results values('Organizer can check in',true); end; $$;
reset role; update public.registrations set registration_status='CANCELLED' where id=current_setting('arenax.test_reg')::uuid; set local role authenticated;
do $$ begin begin perform public.check_in_event_participant(current_setting('arenax.test_event')::uuid,'a289ed2b-99c9-4aad-affc-d3ca89ebcfbb'); raise exception 'Unexpected success: cancelled registration rejected'; exception when sqlstate '22023' then null; end; insert into arenax_test_results values('cancelled registration rejected',true); end; $$;
reset role; update public.registrations set registration_status='APPROVED',payment_status='PENDING' where id=current_setting('arenax.test_reg')::uuid; set local role authenticated;
do $$ begin begin perform public.check_in_event_participant(current_setting('arenax.test_event')::uuid,'a289ed2b-99c9-4aad-affc-d3ca89ebcfbb'); raise exception 'Unexpected success: unsettled registration rejected'; exception when sqlstate '22023' then null; end; insert into arenax_test_results values('unsettled registration rejected',true); end; $$;
reset role; update public.registrations set payment_status='NOT_REQUIRED' where id=current_setting('arenax.test_reg')::uuid; update public.team_members set status='REMOVED' where id=current_setting('arenax.test_member')::uuid; set local role authenticated;
do $$ begin begin perform public.check_in_event_participant(current_setting('arenax.test_event')::uuid,'a289ed2b-99c9-4aad-affc-d3ca89ebcfbb'); raise exception 'Unexpected success: removed roster member rejected'; exception when sqlstate '22023' then null; end; insert into arenax_test_results values('removed roster member rejected',true); end; $$;
reset role; update public.team_members set status='ACTIVE' where id=current_setting('arenax.test_member')::uuid; insert into public.waivers(event_id,title,waiver_text) values(current_setting('arenax.test_event')::uuid,'Test waiver','Transactional test only'); set local role authenticated;
do $$ begin begin perform public.check_in_event_participant(current_setting('arenax.test_event')::uuid,'a289ed2b-99c9-4aad-affc-d3ca89ebcfbb'); raise exception 'Unexpected success: missing versioned waiver acceptance rejected'; exception when sqlstate '22023' then null; end; insert into arenax_test_results values('missing versioned waiver acceptance rejected',true); end; $$;
reset role; update public.events set status='COMPLETED' where id=current_setting('arenax.test_event')::uuid; set local role authenticated;
do $$ begin begin perform public.check_in_event_participant(current_setting('arenax.test_event')::uuid,'3514e1cc-fca6-478b-a760-cb83eefac27e'); raise exception 'Unexpected success: completed event rejects check-in'; exception when sqlstate '22023' then null; end; insert into arenax_test_results values('completed event rejects check-in',true); end; $$;
reset role; select set_config('request.jwt.claim.sub','',true); select set_config('request.jwt.claims','{}',true); set local role anon;
do $$ begin begin perform public.check_in_event_participant(current_setting('arenax.test_event')::uuid,'3514e1cc-fca6-478b-a760-cb83eefac27e'); raise exception 'Anonymous access unexpectedly succeeded'; exception when insufficient_privilege then null; end; end; $$;
reset role;
insert into arenax_test_results values('anonymous execution denied',true);
select jsonb_build_object('passed',count(*),'tests',jsonb_agg(test order by test)) as verification from arenax_test_results;
rollback;
